"""Text-to-SQL harness: draft -> execute -> evidence-backed repair.

Contract (fixed): solve(task, env) -> {"sql": str}
  task  {"id", "db_id", "question", "hint"}      (hint is BIRD's evidence; "" for Spider)
  env.chat(messages, max_tokens=None) -> str     policy call (capped per task: env.max_calls)
  env.schema(db_id) -> str                       CREATE statements of the database
  env.execute(sql, max_rows=20) -> dict          read-only run: {ok, columns, rows, n_rows, error}
  env.descriptions(db_id) -> str                 column descriptions if the dataset ships them, else ""
  env.prompt(name) -> str                        text of a file in this harness
  env.config -> dict                             parsed config.json
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
LITERAL = re.compile(r"'((?:[^']|'')*)'")
CREATE = re.compile(
    r"CREATE\s+(?:TEMP\s+|TEMPORARY\s+)?TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?"
    r"[`\[\"]?([\w ]+?)[`\]\"]?\s*\((.*)\)\s*(?:WITHOUT\s+ROWID\s*)?;",
    re.S | re.I,
)
TEXTY = re.compile(r"CHAR|CLOB|TEXT|STRING|VARCHAR", re.I)
NUMERIC = re.compile(r"INT|REAL|FLOA|DOUB|NUM|DEC|BOOL|DATE|TIME", re.I)

STOP = set(
    """a an the of for in on at to and or is are was were be been being do does did done has have had
    having i me my we our you your he she it its they them their this that these those there here
    what which who whom whose when where why how all any both each few more most other some such no
    nor not only own same so than too very can will just should now would could may might must shall
    let lets please show shows showed list lists give gives find finds tell name names named called
    id ids number numbers count many much total sum average avg maximum minimum max min highest
    lowest greatest least top first second third last next detail details information info data
    record records row rows value values result results table tables column columns database query
    sql select from where group order by limit with without within among between across per also
    either neither every everybody everyone everything anybody anyone anything somebody someone
    something none null true false yes use using used one two three four five ten sorted sort
    ascending descending asc desc different distinct common than then if else as into out up down
    over under above below about against along around because before after during while until upon
    via versus vs etc eg ie dont doesn't isn't aren't what's who's list's am pm ok okay new old
    """.split()
)


def extract_sql(text):
    blocks = [b.strip() for b in SQL_BLOCK.findall(text or "") if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    return (text or "").strip().rstrip(";").strip()


def _literals(sql):
    vals = []
    for m in LITERAL.finditer(sql or ""):
        v = m.group(1).replace("''", "'").strip()
        if v and len(v) >= 2 and not v.isdigit() and v.upper() not in ("T", "F", "Y", "N"):
            if v not in vals:
                vals.append(v)
    return vals[:4]


def _keywords(text):
    """Content words / quoted phrases from the natural-language question or hint."""
    out = []
    for m in re.finditer(r"'([^']{2,60})'|\"([^\"]{2,60})\"", text or ""):
        v = (m.group(1) or m.group(2) or "").strip()
        if v and v not in out:
            out.append(v)
    for w in re.findall(r"[A-Za-z][A-Za-z_\-]{2,}", text or ""):
        lw = w.lower()
        if lw in STOP or lw in [o.lower() for o in out]:
            continue
        out.append(w)
    return out[:8]


def _tables(schema):
    """[(table, [(col, type)])] parsed from CREATE TABLE statements."""
    out = []
    for m in CREATE.finditer(schema or ""):
        table, body = m.group(1).strip(), m.group(2)
        depth, cur, parts = 0, "", []
        for ch in body:
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
            if ch == "," and depth == 0:
                parts.append(cur)
                cur = ""
            else:
                cur += ch
        parts.append(cur)
        cols = []
        for p in parts:
            p = p.strip()
            cm = re.match(r"[`\[\"]?([\w ]+?)[`\]\"]?\s*(.*)$", p, re.S)
            if not cm:
                continue
            cname = cm.group(1).strip()
            if cname.upper() in ("PRIMARY", "FOREIGN", "UNIQUE", "CHECK", "CONSTRAINT", "KEY"):
                continue
            rest = cm.group(2) or ""
            tm = re.match(r"[`\[\"]?(\w+)", rest)
            ctype = tm.group(1) if tm else ""
            cols.append((cname, ctype))
        if cols:
            out.append((table, cols))
    return out


def _is_text(ctype):
    if TEXTY.search(ctype or ""):
        return True
    if NUMERIC.search(ctype or ""):
        return False
    return True  # untyped / BLOB columns often hold strings in these datasets


def _fmt(vals, limit=8):
    shown = [repr(v) for v in vals[:limit]]
    if len(vals) > limit:
        shown.append("...")
    return ", ".join(shown)


def _gather_evidence(env, schema, sql, task):
    """Locate where the mentioned values really live; expose bad column references."""
    tables = _tables(schema)
    if not tables:
        return ""
    text_cols = [(t, c) for t, cols in tables for c, ty in cols if _is_text(ty)]
    notes, errors = [], []
    budget = [70]

    def run(q, nrows=8):
        if budget[0] <= 0:
            return None
        budget[0] -= 1
        try:
            r = env.execute(q, max_rows=nrows)
        except Exception as e:
            msg = str(e)
            if msg not in errors:
                errors.append(msg)
            return None
        if not r.get("ok"):
            msg = str(r.get("error") or "")
            if msg and msg not in errors:
                errors.append(msg)
            return None
        return r

    terms = _literals(sql)
    for k in _keywords(task.get("question", "")) + _keywords(task.get("hint", "")):
        if len(terms) >= 6:
            break
        if k.lower() not in [t.lower() for t in terms]:
            terms.append(k)

    for term in terms:
        core = re.sub(r"[^A-Za-z0-9 ]", " ", term).split()
        key = max(core, key=len) if core else term
        key = key[:30]
        if len(key) < 3:
            continue
        esc = key.replace("'", "''").lower()
        exact, partial = [], []
        for t, c in text_cols:
            if budget[0] <= 0:
                break
            r = run(
                f'SELECT DISTINCT "{c}" FROM "{t}" '
                f"WHERE LOWER(\"{c}\") = '{esc}' LIMIT 3", 3
            )
            if r and r.get("rows"):
                exact.append(f'{t}.{c} = {_fmt([str(x[0]) for x in r["rows"]], 3)}')
                continue
            r = run(
                f'SELECT DISTINCT "{c}" FROM "{t}" '
                f"WHERE LOWER(\"{c}\") LIKE '%{esc}%' LIMIT 5", 5
            )
            if r and r.get("rows"):
                partial.append(f'{t}.{c} contains it: {_fmt([str(x[0]) for x in r["rows"]], 5)}')
        if exact:
            notes.append(f"Value '{term}' is stored EXACTLY in: " + "; ".join(exact[:4]))
        elif partial:
            notes.append(f"Value '{term}' appears inside: " + "; ".join(partial[:4]))
        else:
            notes.append(
                f"Value '{term}' was NOT found in any text column of this database "
                "(it may be spelled differently, or stored as a number/code)."
            )

    # Categorical columns: show the actual vocabulary so filters can use real values.
    cats = []
    for t, c in text_cols:
        if budget[0] <= 0 or len(cats) >= 6:
            break
        r = run(f'SELECT COUNT(DISTINCT "{c}") FROM "{t}"', 1)
        if not r or not r.get("rows"):
            continue
        try:
            n = int(r["rows"][0][0])
        except Exception:
            continue
        if not (1 <= n <= 12):
            continue
        r = run(f'SELECT DISTINCT "{c}" FROM "{t}" LIMIT 12', 12)
        if r and r.get("rows"):
            cats.append(f'{t}.{c}: {_fmt([str(x[0]) for x in r["rows"]], 12)}')
    if cats:
        notes.append("Distinct values of small categorical text columns:\n" + "\n".join(cats))

    if errors:
        notes.append(
            "SQLite rejected some column references while probing (these reveal the REAL column "
            "names; any query using a name listed here is invalid):\n" + "\n".join(errors[:6])
        )
    return "\n".join(notes)[:3500]


def _result_note(res):
    if not res.get("ok"):
        return f"ERROR: {res.get('error')}"
    if res.get("n_rows", 0) == 0:
        return "The query executed but returned ZERO rows."
    return None


def solve(task, env):
    schema = env.schema(task["db_id"])
    user = f"Database: {task['db_id']}\n\nSchema:\n{schema}\n\nQuestion: {task['question']}"
    if task.get("hint"):
        user += f"\nHint: {task['hint']}"
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""
    if desc.strip():
        user += f"\n\nColumn descriptions:\n{desc.strip()[:2000]}"

    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=env.config.get("max_tokens", 800))
    sql = extract_sql(reply)

    try:
        res = env.execute(sql, max_rows=20)
    except Exception as e:
        res = {"ok": False, "error": str(e), "rows": [], "n_rows": 0}

    note = _result_note(res)
    if note is None:
        return {"sql": sql}

    # Draft errored or came back empty: gather evidence and ask for one repair.
    evidence = ""
    try:
        evidence = _gather_evidence(env, schema, sql, task)
    except Exception:
        evidence = ""

    repair = f"Your draft query:\n```sql\n{sql}\n```\n{note}\n"
    if evidence:
        repair += f"\nEvidence gathered from the actual database:\n{evidence}\n"
    repair += (
        "\nThe question almost certainly has a non-empty answer. Diagnose why the draft fails and "
        "write a corrected query. Check these causes in order:\n"
        "1. WRONG COLUMN: the mentioned value may live in a different column or a different table "
        "than the one you filtered (e.g. the free-text/body/description column of the entity being "
        "asked about, not a name/title column of a joined parent table; a full program/degree name "
        "column, not a summary column). Use the evidence above to pick the column that really "
        "contains the value, and drop joins that are not needed.\n"
        "2. NON-EXISTENT COLUMN: only use column names that appear in the CREATE statements. If a "
        "probe error above says 'no such column', that name is invented — replace it with the real "
        "one from the schema.\n"
        "3. VALUE FORMAT: stored values differ in case, spacing, or are embedded in longer text. "
        "Prefer LOWER(col) LIKE '%keyword%' with a distinctive keyword, and keep trailing spaces "
        "when the question quotes them.\n"
        "4. NULL / NEGATION: NOT IN over a nullable subquery returns nothing — use NOT EXISTS. For "
        "'has no X' over a relation table, check BOTH sides of the relation, and make sure the "
        "subquery is correlated to the outer row (alias the outer table and reference that alias).\n"
        "5. JOIN KEYS: verify direction and id column against the FOREIGN KEY clauses.\n"
        "Keep the projection exactly as the question asks. Return ONLY the corrected query in a "
        "single ```sql block."
    )
    messages.append({"role": "assistant", "content": reply})
    messages.append({"role": "user", "content": repair})
    try:
        reply2 = env.chat(messages, max_tokens=env.config.get("max_tokens", 800))
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    try:
        res2 = env.execute(sql2, max_rows=20)
    except Exception:
        res2 = {"ok": False}
    if res2.get("ok"):
        return {"sql": sql2}
    return {"sql": sql}

